// Clamp downstream gRPC + JDBC timeout to remaining request budget
long remainingMs = DeadlineContext.remainingMillis(3_000L); // default edge cap
long hopBudgetMs = Math.min(remainingMs - 75L, 2_500L);
if (hopBudgetMs <= 50L) {
    throw new DeadlineExceededException("Insufficient budget: " + remainingMs + "ms");
}
try (PreparedStatement ps = conn.prepareStatement(
        "SELECT /*+ MAX_EXECUTION_TIME(" + hopBudgetMs + ") */ price FROM pricing WHERE sku = ?")) {
    ps.setQueryTimeout((int) Math.max(1, Math.ceil(hopBudgetMs / 1000.0)));
    Context.current().addListener(ctx -> { try { ps.cancel(); } catch (SQLException ignored) {} }, cancelExec);
    return ps.executeQuery();
}
